#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class DiplomaticExpansionCapture:MonoBehaviour
{
 string folder;int checks;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Begin(){if(!Environment.GetCommandLineArgs().Contains("-diplomatic-expansion-capture"))return;var go=new GameObject("Diplomatic expansion checks");DontDestroyOnLoad(go);go.AddComponent<DiplomaticExpansionCapture>();}
 void Check(bool ok,string note){if(!ok)throw new Exception(note);checks++;}
 IEnumerator Start(){folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/DiplomaticExpansion"));Directory.CreateDirectory(folder);SaveGames.TestRoot=Path.Combine(folder,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.json");var run=Run();while(true){object next=null;bool more=false;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"checks.txt"),"FAILED "+checks+"\n"+ex);Application.Quit(1);yield break;}if(!more)break;yield return next;}File.WriteAllText(Path.Combine(folder,"checks.txt"),checks+" diplomatic expansion checks passed");Application.Quit(0);}
 IEnumerator Run(){yield return null;SaveMenu.StartCampaign(false);yield return new WaitForSecondsRealtime(2);CampaignHUD.Instance.DismissReport();VariableSingleton.SetInt("iMoney",100000);VariableSingleton.SetInt("iCavalry",400);var baseline=VariableSingleton.Instance.CaptureState();var council=FindObjectOfType<CouncilUI>(true);
 VariableSingleton.ChangeBool("bStraitsOpen",false);VariableSingleton.ChangeBool(CourtRoster.Keys[3],false);Check(CandarDiplomacy.UnlockReason!=null,"Candar locked");VariableSingleton.ChangeBool("bStraitsOpen",true);VariableSingleton.ChangeBool(CourtRoster.Keys[3],true);Check(CandarDiplomacy.OpenNegotiations(out _),"Candar opens through Orhan");Check(!CandarDiplomacy.OpenNegotiations(out _),"no duplicate opening");int secrets=DailyLifeEvents.I("iSecrets");for(int i=0;i<3;i++)Check(CandarDiplomacy.PurchaseSecret(out _),"three finite secrets");int gold=DailyLifeEvents.I("iMoney");Check(!CandarDiplomacy.PurchaseSecret(out _)&&DailyLifeEvents.I("iMoney")==gold&&DailyLifeEvents.I("iSecrets")==secrets+3,"exhausted secrets no payment");long population=PopulationAccounting.People;Check(CandarDiplomacy.Ransom(out _),"ransom works");Check(PopulationAccounting.People-population>=150&&PopulationAccounting.People-population<=300,"ransom inclusive population");Check(!CandarDiplomacy.Ransom(out _),"weekly ransom cooldown");Check(CandarDiplomacy.Disrupt(out _),"buy disruption");Check(!CandarDiplomacy.DelayOperation(OttomanDirector.Operation.Resupply,out _),"supply emergency unaffected");Check(CandarDiplomacy.DelayOperation(OttomanDirector.Operation.Bombard,out _),"land operation delayed");SaveGames.Checkpoint();var saved=SaveGames.Read(VariableSingleton.SavePath);VariableSingleton.Instance.RestoreValidated(saved.campaign);Check(CandarDiplomacy.DelayPending&&CandarDiplomacy.SecretsRemaining==0,"Candar saved state");
 VariableSingleton.Instance.RestoreValidated(baseline);double stock=SharedProvisions.Stock(SharedProvisions.City);Check(RagusaDiplomacy.RequestFood(out _),"Ragusa provision commitment");Check(SharedProvisions.Stock(SharedProvisions.City)==stock,"no instant food");Check(!RagusaDiplomacy.RequestFood(out _),"monthly gate");RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(14));RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(14));Check(SharedProvisions.Stock(SharedProvisions.City)==stock+500,"one shared stock delivery");int foot=DailyLifeEvents.I("iInfantry");Check(RagusaDiplomacy.StartContract(out _),"Ragusa troop contract");Check(DailyLifeEvents.I("iInfantry")==foot-500&&RagusaDiplomacy.CommittedTroops==1200,"deployment reservation");RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(90));int returning=TrainingPool.Orders.Where(o=>o.kind==RagusaDiplomacy.ExpeditionReturn).Sum(o=>o.quantity);Check(returning>0&&returning<1200&&TrainingPool.Orders.All(TrainingPool.IsValidOrder),"valid survivors and saved return orders");TrainingPool.CompleteDueOrders(VariableSingleton.GetDate().AddDays(104));RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(104));Check(!RagusaDiplomacy.ContractActive&&DailyLifeEvents.I("iInfantry")>foot-500,"survivors return");
 VariableSingleton.Instance.RestoreValidated(baseline);VariableSingleton.ChangeBool("bStraitsOpen",true);CircassianOutpost.Establish();CircassianOutpost.SetCargo(true);Check(CircassianOutpost.Established,"Copa compound");int day=CountryDiplomacy.Day;double reserve=SharedProvisions.Stock("CopaExport");for(int d=1;d<=7;d++)CircassianOutpost.Advance(VariableSingleton.GetDate().AddDays(d));Check(SharedProvisions.Stock("CopaExport")==reserve-CircassianOutpost.FoodQuantity,"finite food deducted on departure");Check(SharedProvisions.Stock(SharedProvisions.City)==stock,"no teleport from Copa");SaveGames.Checkpoint();saved=SaveGames.Read(VariableSingleton.SavePath);VariableSingleton.Instance.RestoreValidated(saved.campaign);Check(CircassianOutpost.Established&&SharedProvisions.Stock("CopaExport")==reserve-CircassianOutpost.FoodQuantity,"outpost and stock saved");VariableSingleton.SetInt("iDiplomacyCopaShipFate1",0);double beforeDelivery=SharedProvisions.Stock(SharedProvisions.City);CircassianOutpost.Advance(VariableSingleton.GetDate().AddDays(21));double delivered=SharedProvisions.Stock(SharedProvisions.City);Check(delivered==beforeDelivery+CircassianOutpost.FoodQuantity,"Copa cargo arrives once");CircassianOutpost.Advance(VariableSingleton.GetDate().AddDays(21));Check(SharedProvisions.Stock(SharedProvisions.City)==delivered,"Copa delivery cannot duplicate");VariableSingleton.ChangeBool("bStraitsOpen",false);int voyages=DailyLifeEvents.I("iDiplomacyCopaSerial");CircassianOutpost.Advance(VariableSingleton.GetDate().AddDays(42));Check(DailyLifeEvents.I("iDiplomacyCopaSerial")==voyages,"closed Bosphorus holds Copa departures");Check(CountryDiplomacy.Index("gazaria")>=31&&CountryDiplomacy.Index("gazaria")!=CountryDiplomacy.Index("genoa"),"separate Gazaria");Check(WarTheatre.Find("gazaria").group=="gazaria"&&WarTheatre.Find("candar").kind=="province","map identity preserved");
 VariableSingleton.ChangeBool("bStraitsOpen",true);VariableSingleton.ChangeBool(CourtRoster.Keys[3],true);CandarDiplomacy.OpenNegotiations(out _);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.4f);foreach(string scene in new[]{"candar","ragusa","gazaria","copa","theodoro"}){WarTheatreUI.Close();if(scene=="candar")council.CandarCourt();else if(scene=="ragusa")council.RagusanCourt();else if(scene=="gazaria")council.GazariaCourt();else if(scene=="theodoro")council.TheodoroCourt();else council.CircassianPort();yield return null;Canvas.ForceUpdateCanvases();var root=GameObject.Find("Council screen");Check(root!=null&&root.activeInHierarchy,"court screen active "+scene);if(scene=="theodoro")Check(GameObject.Find("Theodoro encounter")!=null,"Theodoro desk visible");foreach(var t in root.GetComponentsInChildren<TMP_Text>())Check(!t.isTextOverflowing,"text fits "+scene+" "+t.text);foreach(var image in root.GetComponentsInChildren<RawImage>())Check(image.texture!=null,"art loads "+scene);ScreenCapture.CaptureScreenshot(Path.Combine(folder,scene+"-"+size.x+".png"));yield return new WaitForSecondsRealtime(.2f);ControlSingleton.Instance.GoBack();yield return null;}}
 }
}
#endif
